exec(open('/tmp/multi_fit.py').read().split('for lo,hi,deg')[0])

def objective(data,v,deg,bounds=None):
 if bounds:
  for z,(a,b) in zip(v,bounds):
   if z<a or z>b:return 1e40 + sum((a-z)**2 if z<a else (z-b)**2 if z>b else 0 for z,(a,b) in zip(v,bounds))*1e20
 p=[(v[i],exp(v[i+1])) for i in range(0,len(v),2)]
 return fit(data,p,deg)[0]

def nm(data,init,deg,bounds,maxit=3000):
 v=[]
 for x,g in init:v += [x,log(g)]
 n=len(v); simplex=[v[:]]
 # use scales x0 30-100, loggamma .2
 scales=[]
 for i in range(n):
  scales.append(50 if i%2==0 else .2)
 for j in range(n):
  q=v[:]; q[j]+=scales[j]; simplex.append(q)
 vals=[objective(data,q,deg,bounds) for q in simplex]
 for it in range(maxit):
  order=sorted(range(n+1),key=lambda i:vals[i]); simplex=[simplex[i] for i in order];vals=[vals[i] for i in order]
  # convergence in objective and coordinates
  if max(max(abs(simplex[i][j]-simplex[0][j]) for j in range(n)) for i in range(1,n+1))<1e-7: break
  c=[sum(simplex[i][j] for i in range(n))/n for j in range(n)]
  # reflection
  r=[c[j]+(c[j]-simplex[-1][j]) for j in range(n)]; vr=objective(data,r,deg,bounds)
  if vals[0] <= vr < vals[-2]: simplex[-1],vals[-1]=r,vr
  elif vr<vals[0]:
   e=[c[j]+2*(r[j]-c[j]) for j in range(n)];ve=objective(data,e,deg,bounds)
   simplex[-1],vals[-1]=(e,ve) if ve<vr else (r,vr)
  else:
   if vr<vals[-1]:
    cc=[c[j]+.5*(r[j]-c[j]) for j in range(n)]
   else:
    cc=[c[j]+.5*(simplex[-1][j]-c[j]) for j in range(n)]
   vc=objective(data,cc,deg,bounds)
   if vc<vals[-1]:simplex[-1],vals[-1]=cc,vc
   else:
    for i in range(1,n+1):
     simplex[i]=[simplex[0][j]+.5*(simplex[i][j]-simplex[0][j]) for j in range(n)]
     vals[i]=objective(data,simplex[i],deg,bounds)
 i=min(range(n+1),key=lambda i:vals[i]);v=simplex[i];p=[(v[i],exp(v[i+1])) for i in range(0,len(v),2)];sse,q=fit(data,p,deg)
 return p,q,(sse/len(data))**.5,it

for win in [(15000,18000),(15500,18000),(15000,17500),(15500,17500),(15800,17500),(16000,17500),(15500,18500)]:
 d=[r for r in rows if win[0]<=r[0]<=win[1]]
 print('\nWIN',win,'n',len(d))
 for deg in [1,2,3,4]:
  for init in [[(17330,300),(16210,200)],[(17300,600),(16200,220)]]:
   p,q,rm,it=nm(d,init,deg,[(16800,18000),(log(20),log(2000)),(15900,16500),(log(20),log(1000))],2000)
   print('d',deg,'p',[(round(a,5),round(b,5)) for a,b in p],'q',[round(z,5) for z in q], 'rm',round(rm,5),'it',it)
