# fit background forms on x 15000-18500, excluding peak candidate ranges with standard grid
from pathlib import Path
from math import exp
r=[]
for l in Path('/app/graphene.dat').read_text().splitlines():
 if l.strip():
  a,b=l.split('\t');r.append((float(a.replace(',','.')),float(b.replace(',','.'))))
# simple 2 basis linear solver
exec(open('/tmp/multi_fit.py').read().split('for lo,hi,deg')[0].split("exec(open('/tmp/multi_fit.py')")[0] if False else '')
def linfit(A,y):
 m=len(A[0]); M=[[sum(a[i]*a[j] for a in A) for j in range(m)]+[sum(a[i]*b for a,b in zip(A,y))] for i in range(m)]
 for c in range(m):
  q=max(range(c,m),key=lambda i:abs(M[i][c]));M[c],M[q]=M[q],M[c];z=M[c][c];M[c]=[v/z for v in M[c]]
  for i in range(m):
   if i!=c:
    z=M[i][c];M[i]=[u-z*v for u,v in zip(M[i],M[c])]
 return [M[i][-1] for i in range(m)]
for exclude in [[],[(16000,16500)],[(16000,16500),(17000,17700)],[(15800,16600),(16800,17800)],[(16000,16500),(17000,17600)]]:
 d=[z for z in r if 15000<=z[0]<=18500 and not any(a<=z[0]<=b for a,b in exclude)]
 print('\nexclude',exclude,'n',len(d))
 for tau in [300,500,700,1000,1500,2000,3000,5000,10000]:
  # exp decays to lower x; x high greater
  A=[[1,exp((x-17000)/tau)] for x,y in d];q=linfit(A,[y for x,y in d]);rm=(sum((y-(q[0]+q[1]*a[1]))**2 for a,(x,y) in zip(A,d))/len(d))**.5
  print(tau,'rm',round(rm), 'off',round(q[0]),'A',round(q[1]),'pred17330',round(q[0]+q[1]*exp(330/tau)))
