def solve(A,b):
 m=len(A[0]);M=[[sum(a[i]*a[j] for a in A)+ (1e-9 if i==j else 0) for j in range(m)]+[sum(a[i]*v for a,v in zip(A,b))] for i in range(m)]
 for c in range(m):
  q=max(range(c,m),key=lambda i:abs(M[i][c])); M[c],M[q]=M[q],M[c];z=M[c][c];M[c]=[v/z for v in M[c]]
  for i in range(m):
   if i!=c:
    z=M[i][c];M[i]=[u-z*v for u,v in zip(M[i],M[c])]
 return [M[i][-1] for i in range(m)]
for tau in [500,600,700,800,900]:
